export type Card = {
  monster: string;
  rank?: number;
};

const POINTS_PER_SPHINX = 1;
const MAX_TYPES_FOR_BASE_BONUS = 3;
const BASE_BONUS = 1;
const POINTS_PER_EXTRA_TYPE = 2;

const typeBonus = (typeCount: number): number => {
  if (typeCount <= MAX_TYPES_FOR_BASE_BONUS) return BASE_BONUS;

  const typesBeyondThreshold = typeCount - MAX_TYPES_FOR_BASE_BONUS - 1;
  return POINTS_PER_EXTRA_TYPE * typesBeyondThreshold;
};

export const sphinxScore = (army: Card[]): number => {
  const distinctMonsterTypes = new Set(army.map((card) => card.monster));
  if (!distinctMonsterTypes.has("sphinx")) return 0;

  return POINTS_PER_SPHINX + typeBonus(distinctMonsterTypes.size);
};

