export type Card = {
  monster: string;
  rank?: number;
};

const POINTS_PER_SPHINX = 1;
const TYPES_INCLUDED_IN_BASE_BONUS = 4;
const BASE_BONUS = 1;
const POINTS_PER_EXTRA_TYPE = 2;

const typeBonus = (typeCount: number): number => {
  const typesBeyondBase = typeCount - TYPES_INCLUDED_IN_BASE_BONUS;
  if (typesBeyondBase < 0) return BASE_BONUS;

  return POINTS_PER_EXTRA_TYPE * typesBeyondBase;
};

export const sphinxScore = (army: Card[]): number => {
  const distinctMonsterTypes = new Set(army.map((card) => card.monster));
  const sphinxCount = army.filter((card) => card.monster === "sphinx").length;

  return sphinxCount * (POINTS_PER_SPHINX + typeBonus(distinctMonsterTypes.size));
};

